-- Removes what the browser tests made on the local copy: only accounts whose email looks like
-- a test address (name-<digits>-<digits>@example.com) and everything they own, never your own
-- accounts. Run by scripts/test-e2e-local.sh after each run.
begin;
set local session_replication_role = replica;
create temp table t as select id from auth.users where email ~ '-[0-9]+-[0-9]+@example\.com$';
create temp table ts as select id from public.sellers where owner_user_id in (select id from t);
delete from public.verification_history where seller_id in (select id from ts);
delete from public.verification_requests where seller_id in (select id from ts);
delete from public.media_assets where entity_id in (select id from public.products where seller_id in (select id from ts));
delete from public.product_publication_ledger where seller_id in (select id from ts);
delete from public.product_view_days where product_id in (select id from public.products where seller_id in (select id from ts));
delete from public.product_view_totals where product_id in (select id from public.products where seller_id in (select id from ts));
delete from public.reviews where author_id in (select id from t) or product_id in (select id from public.products where seller_id in (select id from ts));
delete from public.favourites where user_id in (select id from t) or product_id in (select id from public.products where seller_id in (select id from ts));
delete from public.vehicle_view_days where vehicle_listing_id in (select id from public.vehicle_listings where seller_id in (select id from ts));
delete from public.vehicle_view_totals where vehicle_listing_id in (select id from public.vehicle_listings where seller_id in (select id from ts));
delete from public.media_assets where entity_type = 'vehicle' and entity_id in (select id from public.vehicle_listings where seller_id in (select id from ts));
delete from public.contact_enquiries where vehicle_listing_id in (select id from public.vehicle_listings where seller_id in (select id from ts));
delete from public.audit_logs where target_id in (select id::text from public.vehicle_listings where seller_id in (select id from ts));
delete from public.vehicle_listings where seller_id in (select id from ts);
delete from public.messages where conversation_id in (select id from public.conversations where buyer_id in (select id from t) or seller_id in (select id from ts));
delete from public.conversation_reads where conversation_id in (select id from public.conversations where buyer_id in (select id from t) or seller_id in (select id from ts));
delete from public.audit_logs where target_id in (select id::text from public.conversations where buyer_id in (select id from t) or seller_id in (select id from ts));
delete from public.conversations where id in (select id from public.conversations where buyer_id in (select id from t) or seller_id in (select id from ts));
delete from public.products where seller_id in (select id from ts);
delete from public.seller_private where seller_id in (select id from ts);
delete from public.sellers where id in (select id from ts);
delete from public.user_role_permissions where user_role_id in (select id from public.user_roles where user_id in (select id from t));
delete from public.user_roles where user_id in (select id from t);
delete from public.background_jobs where user_id in (select id from t) or idempotency_key in (select 'application:'||a.id||':received:'||b.user_id from public.role_applications a cross join public.user_roles b where a.applicant_id in (select id from t) and b.role_key='super_admin');
delete from public.seller_staff_permissions where membership_id in (select id from public.seller_staff_memberships where user_id in (select id from t) or seller_id in (select id from ts));
delete from public.seller_staff_memberships where user_id in (select id from t) or seller_id in (select id from ts);
delete from public.seller_invitations where seller_id in (select id from ts) or invitee_email ~ '-[0-9]+-[0-9]+@example\.com$';
delete from public.background_jobs where payload ->> 'to' ~ '-[0-9]+-[0-9]+@example\.com$';
delete from public.blog_comments where author_id in (select id from t) or post_id in (select id from public.blog_posts where author_id in (select id from t));
delete from public.media_assets where entity_type = 'blog_post' and entity_id in (select id from public.blog_posts where author_id in (select id from t));
delete from public.blog_post_tags where post_id in (select id from public.blog_posts where author_id in (select id from t));
delete from public.blog_read_days where post_id in (select id from public.blog_posts where author_id in (select id from t));
delete from public.blog_read_totals where post_id in (select id from public.blog_posts where author_id in (select id from t));
delete from public.blog_posts where author_id in (select id from t);
delete from public.role_applications where applicant_id in (select id from t);
delete from public.notifications where user_id in (select id from t);
delete from public.payment_transactions where order_id in (select id from public.orders where seller_id in (select id from ts) or buyer_id in (select id from t));
delete from public.orders where seller_id in (select id from ts) or buyer_id in (select id from t);
delete from public.payment_accounts where seller_id in (select id from ts);
delete from public.invoices where list_id in (select id from public.email_lists where seller_id in (select id from ts));
delete from public.email_campaigns where list_id in (select id from public.email_lists where seller_id in (select id from ts));
delete from public.list_subscribers where list_id in (select id from public.email_lists where seller_id in (select id from ts)) or user_id in (select id from t) or email ~ '-[0-9]+-[0-9]+@example\.com$';
delete from public.email_lists where seller_id in (select id from ts);
delete from public.audit_logs where action in ('bulk_email.enable', 'bulk_email.disable', 'email_list.add', 'email_campaign.send') and target_id in (select id::text from ts);
delete from public.referral_attributions where referred_user_id in (select id from t) or referrer_user_id in (select id from t);
delete from public.audit_logs where target_id in (select id::text from public.referral_codes where owner_user_id in (select id from t));
delete from public.referral_codes where owner_user_id in (select id from t);
delete from public.notification_preferences where user_id in (select id from t);
delete from public.audit_logs where actor_id in (select id from t) or target_id in (select id::text from ts);
delete from public.platform_settings_history where actor_id in (select id from t);
update public.platform_settings set updated_by = null where updated_by in (select id from t);
delete from public.profiles where id in (select id from t);
delete from auth.users where id in (select id from t);
delete from public.rate_limit_counters;
delete from public.advertisements where created_by in (select id from t);
-- Phone notification devices and choices (cascades are off here, so they are removed by hand).
delete from public.push_subscriptions where user_id in (select id from t);
delete from public.push_preferences where user_id in (select id from t);
delete from public.background_jobs where type = 'push' and user_id in (select id from t);
-- popup cleanup
delete from public.background_jobs where payload ->> 'to' ~ '^popup-[0-9]+-[0-9]+@example\.com$';
delete from public.list_subscribers where email ~ '^popup-[0-9]+-[0-9]+@example\.com$';
commit;
